void Debug_Statistics::Record_DX8_Polys_And_Vertices(int polys, int verts, const ShaderClass &shader)
{
	int n;
	if (shader.flags & 2)
	{
		DX8Caps *caps = DX8Wrapper::Read_CurrentCaps();
		if (caps->SupportNPatches)
		{
			unsigned level = WW3D::Read_NPatchesLevel();
			n = (int)(level * level * (unsigned)polys);
		}
		else
		{
			n = polys;
		}
	}
	else
	{
		n = polys;
	}
	g_stat0 += n;
	g_stat1 += verts;
	g_stat8 += 1;
}

